const routeNames = { '/business': ['集团业务', 'Group business'], '/services': ['产品能力', 'Products'], '/solutions': ['行业方案', 'Solutions'], '/opportunities': ['全球信号', 'Market signals'], '/ecosystem': ['开放生态', 'Ecosystem'], '/insights': ['洞察与观点', 'Insights'], '/about': ['关于算链', 'About CCT'], '/contact': ['与我们联系', 'Contact'], '/privacy': ['隐私政策', 'Privacy policy'], '/terms': ['使用条款', 'Terms of use'] };
