function ContactPage() {
  const { lang, data } = useSite();
  const [params] = useSearchParams();
  const [form, setForm] = useState({ name: '', email: '', company: '', interest: params.get('interest') || '', message: '', consent: false, website: '' });
  const [busy, setBusy] = useState(false), [error, setError] = useState(''), [done, setDone] = useState(false);
  const change = e => setForm(f => ({ ...f, [e.target.name]: e.target.type === 'checkbox' ? e.target.checked : e.target.value }));
  const interests = [['推理基础设施与 FinOps', 'Inference fabric & FinOps'], ['企业智能体与工作流', 'Enterprise agents & workflows'], ['私有 AI 与数据主权', 'Private AI & data sovereignty'], ['GEO 增长智能系统', 'GEO growth intelligence'], ['行业 AI 解决方案', 'Industry AI solutions'], ['生态与联合试点', 'Ecosystem & joint pilots'], ['其他需求', 'Other enquiries']];
  async function submit(e) {
    e.preventDefault(); if (busy) return; setBusy(true); setError('');
    try {
      if (staticSite) throw new Error(copy(lang, '当前公开站点不收集联系信息。请在正式业务邮箱配置完成后使用联系渠道。', 'This public site does not collect contact details. Please use the verified business email once it is configured.'));
      const res = await fetch('/api/public/leads', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(form) });
      const result = await res.json();
      if (!res.ok) throw new Error(lang === 'en' ? (res.status === 429 ? 'Too many requests. Please try again later.' : 'Unable to submit. Please check your details and try again.') : (Object.values(result.fields || {}).flat().filter(Boolean).join(' ') || result.error || '提交失败，请重试。'));
      setDone(true);
    } catch (err) { setError(err.message || copy(lang, '连接失败，请稍后重试。', 'Connection failed. Please try again.')); }
    finally { setBusy(false); }
  }
  const email = data?.settings?.contactEmail;
  return <><PageIntro eyebrow="LET’S BUILD WHAT’S NEXT" title={copy(lang, '好的改变，\n从一次对话开始。', 'Meaningful change.\nOne conversation away.')} description={copy(lang, '告诉我们你的业务挑战、技术方向或合作想法。我们期待与你一起，找到值得落地的下一步。', 'Tell us about your business challenge, technology goals or partnership idea. Let’s explore a practical next step.')}/><section className="site-container site-contact-layout"><aside className="site-contact-aside"><span className="site-eyebrow">CONNECT WITH CCT</span><h2>{copy(lang, '从你的需求出发。', 'Start with your needs.')}</h2><p>{copy(lang, '无论是一个明确的项目，还是尚待探索的方向，我们都愿意认真了解。', 'Whether you have a defined project or a direction to explore, we’re ready to listen.')}</p><div className="site-contact-points">{[[Radar,'描述业务场景','Describe your context'],[Layers3,'梳理技术与资源','Explore technology and resources'],[Network,'找到合作切入点','Find common ground']].map(([Icon,zh,en])=><div key={en}><Icon size={18}/><span>{copy(lang,zh,en)}</span></div>)}</div>{email && !email.endsWith('.example') && <a className="site-contact-email" href={`mailto:${email}`}><Mail size={18}/>{email}</a>}<div className="site-contact-note"><ShieldCheck size={18}/><p>{copy(lang, staticSite ? '当前永久公开展示端不收集联系信息，也不会将输入发送到任何服务器。正式业务邮箱经集团确认后再开放线上咨询。' : '你的联系信息仅用于处理本次咨询。请不要提交密码、商业机密或敏感个人信息。', staticSite ? 'This permanent public showcase does not collect or transmit contact details. Online enquiries will open after a verified business email is configured.' : 'Your details are used to respond to your enquiry. Please avoid passwords, trade secrets or sensitive personal data.')}</p></div></aside>{staticSite ? <div className="site-contact-static" role="status"><span><ShieldCheck size={32}/></span><div className="site-eyebrow">PRIVACY BY DEFAULT</div><h2>{copy(lang, '公开展示，\n不采集信息。', 'Public showcase.\nNo data collection.')}</h2><p>{copy(lang, '此永久链接用于查看 CCT 官网内容。管理后台、客户咨询与数据库只在受保护的服务端运行；在集团确认正式域名与业务邮箱前，本页面不显示可填写表单。', 'This permanent link presents the CCT website. Administration, enquiries and the database run only on a protected server. The form remains unavailable until the official domain and business email are confirmed.')}</p><Link to="/services" className="site-button site-button-primary">{copy(lang, '继续探索能力', 'Explore capabilities')}<ArrowUpRight size={18}/></Link></div> : done ? <div className="site-contact-success" role="status"><span><Check size={32}/></span><div className="site-eyebrow">MESSAGE RECEIVED</div><h2>{copy(lang, '连接已建立。', 'The conversation has begun.')}</h2><p>{copy(lang, '我们已收到你的需求。团队将结合咨询内容，通过你留下的联系方式与你沟通。', 'We have received your enquiry. Our team will review your needs and use the contact details you provided to get in touch.')}</p><Link to="/services" className="site-button site-button-primary">{copy(lang, '继续探索 CCT', 'Explore CCT')}<ArrowUpRight size={18}/></Link></div> : <form className="site-contact-form" onSubmit={submit}><div className="site-form-heading"><span>01 — {copy(lang, '介绍一下你自己', 'TELL US ABOUT YOURSELF')}</span><small>{copy(lang, '* 为必填项', '* Required fields')}</small></div><div className="site-form-two"><label>{copy(lang,'你的姓名','Your name')} *<input name="name" autoComplete="name" value={form.name} onChange={change} maxLength={80} required placeholder={copy(lang,'如何称呼你','Full name')}/></label><label>{copy(lang,'公司 / 组织','Company / organization')} *<input name="company" autoComplete="organization" value={form.company} onChange={change} maxLength={160} required placeholder={copy(lang,'公司或组织名称','Organization name')}/></label></div><label>{copy(lang,'联系邮箱','Email address')} *<input name="email" type="email" autoComplete="email" value={form.email} onChange={change} maxLength={254} required placeholder="you@company.com"/></label><div className="site-form-heading site-form-heading-next"><span>02 — {copy(lang,'我们可以如何协作','HOW CAN WE WORK TOGETHER?')}</span></div><label>{copy(lang,'感兴趣的方向','Area of interest')} *<select name="interest" required value={form.interest} onChange={change}><option value="">{copy(lang,'请选择合作方向','Select an area')}</option>{form.interest && !interests.some(([zh])=>zh===form.interest) && <option value={form.interest}>{form.interest}</option>}{interests.map(([zh,en])=><option key={zh} value={zh}>{copy(lang,zh,en)}</option>)}</select></label><label>{copy(lang,'告诉我们你的想法','Tell us what you have in mind')} *<textarea name="message" rows={5} minLength={10} maxLength={5000} value={form.message} onChange={change} required placeholder={copy(lang,'你的业务场景、当前挑战，以及希望实现的目标……','Your context, challenges and what you would like to achieve…')}/><span className="site-field-hint">{copy(lang,'至少 10 字，最多 5,000 字','10–5,000 characters')}<span>{form.message.length} / 5,000</span></span></label><label className="site-honeypot" aria-hidden="true">Website<input name="website" tabIndex={-1} autoComplete="off" value={form.website} onChange={change}/></label><label className="site-consent"><input name="consent" type="checkbox" checked={form.consent} onChange={change} required/><span>{copy(lang,'我已阅读','I have read the ')}<Link to="/privacy" target="_blank" rel="noopener">{copy(lang,'《隐私政策》','Privacy Policy')}</Link>{copy(lang,'，并同意使用上述信息处理本次咨询。',' and agree to the use of my details to respond to this enquiry.')}</span></label>{error && <div className="site-form-error" role="alert"><AlertCircle size={18}/>{error}</div>}<button type="submit" className="site-button site-button-primary site-submit" disabled={busy}>{busy ? <LoaderCircle className="site-spin" size={18}/> : <ArrowUpRight size={18}/>} {copy(lang,busy ? '正在提交…' : '发送合作需求',busy ? 'Sending…' : 'Send your enquiry')}</button><p className="site-form-foot">{copy(lang,'期待与你，共同定义下一种可能。','Looking forward to what we can create together.')}</p></form>}</section></>;
}

function DetailPage() {
  const { lang, data, loading } = useSite(), { slug } = useParams();
  const item = data?.content?.find(entry => entry.slug === slug);
  if (loading) return <section className="site-container site-section"><Skeleton/></section>;
  if (!item) return <NotFound/>;
  const parent = item.type === 'service' ? '/services' : item.type === 'solution' ? '/solutions' : item.claimScope === 'market' ? '/opportunities' : '/insights';
  return <><PageIntro eyebrow={item.category || 'CCT PERSPECTIVES'} title={value(item,'title',lang)} description={value(item,'summary',lang)}/><article className="site-container site-article"><aside><Link to={parent}><ArrowRight size={16} style={{transform:'rotate(180deg)'}}/>{routeNames[parent][lang==='zh'?0:1]}</Link><span>{formatDate(item.updatedAt,lang)}</span><EvidenceBadge item={item}/>{item.sourceDate && <span>{copy(lang,'来源日期','Source date')} · {formatDate(item.sourceDate,lang)}</span>}<div className="site-article-aside-mark">CCT<small>COMPUTE CHAIN</small></div></aside><div className="site-article-body">{item.claimScope === 'market' && <div className="site-evidence-notice"><ShieldCheck size={20}/><div><strong>{copy(lang,'外部市场数据','External market data')}</strong><p>{copy(lang,'本页引用第三方官方披露用于判断市场方向，不代表 CCT 自身业绩、规模或承诺。','This page cites official third-party disclosures to interpret the market. It does not represent CCT performance, scale or commitments.')}</p></div></div>}{value(item,'body',lang).split(/\n\s*\n/).map((paragraph,i)=><p key={i}>{paragraph}</p>)}{item.sourceUrl && <a className="site-source-link" href={item.sourceUrl} target="_blank" rel="noreferrer"><span><small>{copy(lang,'原始来源','ORIGINAL SOURCE')}</small><strong>{item.sourceLabel || item.sourceUrl}</strong></span><ExternalLink size={19}/></a>}<div className="site-article-next"><span>{copy(lang,'把想法带入你的业务。','Bring these ideas to your business.')}</span><TextLink to={`/contact?interest=${encodeURIComponent(value(item,'title',lang))}`}>{copy(lang,'与我们讨论','Talk to our team')}</TextLink></div></div></article></>;
}

function LegalPage({type}) {
  const {lang}=useSite(), privacy=type==='privacy';
  const staticPrivacySections=[
    ['当前公开版本','Current public version','本永久公开展示端不提供咨询表单，不收集姓名、公司、邮箱或需求描述，也不连接管理后台与客户数据库。','This permanent public showcase has no enquiry form, collects no names, company details, email addresses or messages, and is not connected to the administration system or customer database.'],
    ['本机偏好','Local preference','网站只在你的设备上保存中英文语言偏好，不配置第三方广告追踪。','The website stores only your language preference on your device and does not configure third-party advertising tracking.'],
    ['后续启用','Future activation','线上咨询只会在集团确认正式域名、业务邮箱、数据处理责任与保留规则后启用，并同步更新本说明。','Online enquiries will be enabled only after the official domain, business email, data responsibility and retention rules are confirmed. This notice will be updated at that time.'],
  ];
  const privacySections=staticSite ? staticPrivacySections : [
    ['我们收集什么','What we collect','当你提交合作咨询时，我们收集你主动填写的姓名、公司、邮箱、合作方向及需求描述，以及你同意本说明的记录。请不要在表单中提交敏感个人信息。','When you submit an enquiry, we collect your name, company, email address, area of interest, message and record of consent. Please do not submit sensitive personal information.'],
    ['信息如何使用','How we use information','信息用于了解需求、处理咨询、安排后续沟通及防止垃圾提交。不会因为一次咨询而默认订阅营销邮件。','We use this information to understand your needs, respond and arrange follow-up, and prevent spam. Submitting an enquiry does not automatically subscribe you to marketing emails.'],
    ['保存与访问','Retention and access','咨询信息由获授权的运营人员访问，用于跟进合作需求。我们按实际业务需要保存信息；不再需要或收到有效删除请求后，应按适用规则处理。','Authorized staff can access enquiries to handle potential collaboration. Information is retained for relevant business needs and should be handled according to applicable requirements when no longer needed or following a valid deletion request.'],
    ['Cookie 与设备偏好','Cookies and preferences','公开网站只在本机保存语言偏好。管理后台使用必要的登录 Cookie 维持会话，退出后会话失效。本站未配置第三方广告追踪。','The public site stores your language preference on your device. The administration area uses an essential session cookie, invalidated on logout. Third-party advertising tracking is not configured.'],
    ['联系我们','Contact us','如需查询、更正或删除已提交的咨询，请通过合作咨询页面说明请求，并提供原提交邮箱以便核实。','To access, correct or request deletion of an enquiry, use the contact form and include the original email address so that your request can be verified.'],
  ];
  const termSections=[
    ['网站信息','Site information','本站展示 CCT 的业务方向、技术能力规划与合作思路。具体服务范围、交付成果、价格与服务水平应以双方确认的合同和项目文件为准。','This site describes CCT’s business directions, planned capabilities and collaboration approach. Scope, deliverables, pricing and service levels are subject to agreed contracts and project documents.'],
    ['可视化与观点','Visualizations and perspectives','图形中的轨道、节点与网络用于概念表达，不是实时算力监控，也不代表已交付设备、真实节点数量或收益承诺。洞察文章供一般交流参考。','Orbital paths, nodes and networks are conceptual illustrations. They are not real-time compute monitoring or evidence of deployed equipment, node counts or financial returns. Insights are provided for general discussion.'],
    ['内容使用','Use of content','请合理使用本网站信息，不得冒用集团名义、破坏网站、绕过访问控制或滥用咨询入口。引用相关内容时请保留出处与上下文。','Use this site responsibly. Do not impersonate the group, disrupt the site, bypass access controls or misuse enquiry forms. Preserve attribution and context when quoting material.'],
    ['沟通与合作','Enquiries and agreements',staticSite?'当前公开展示端不接受线上咨询。未来启用咨询渠道也不自动形成服务合同或投资关系；任何具体承诺需由有权代表以正式文件确认。':'提交表单表示发起咨询，不自动形成服务合同或投资关系。任何具体承诺需要由有权代表的人员以正式文件确认。',staticSite?'The current public showcase does not accept online enquiries. Any future enquiry channel will not create a service contract or investment relationship; specific commitments require formal confirmation by authorized representatives.':'Submitting a form initiates an enquiry. It does not create a service contract or investment relationship. Specific commitments require formal confirmation by authorized representatives.'],
  ];
  return <><PageIntro eyebrow={privacy?'PRIVACY POLICY':'TERMS OF USE'} title={copy(lang,privacy?'尊重每一份信任。':'清晰的规则，\n可信的连接。',privacy?'Respecting your trust.':'Clear terms.\nTrusted connections.')} description={copy(lang,privacy?'关于网站收集与使用咨询信息的说明。':'关于网站信息与使用范围的说明。',privacy?'How this website handles enquiry information.':'How information on this website may be used.')}/><section className="site-container site-legal"><p className="site-legal-date">{copy(lang,'版本日期','Version date')} · 2026.09.25</p>{(privacy?privacySections:termSections).map(([zh,en,body,bodyEn],i)=><section key={en}><span>0{i+1}</span><div><h2>{copy(lang,zh,en)}</h2><p>{copy(lang,body,bodyEn)}</p></div></section>)}<TextLink to="/contact">{copy(lang,'联系我们','Contact us')}</TextLink></section></>;
}
function NotFound(){const{lang}=useSite();return <section className="site-container site-not-found"><span className="site-eyebrow">404 / UNCHARTED TERRITORY</span><h1>{copy(lang,'这个坐标，\n暂时没有内容。','Nothing at\nthese coordinates.')}</h1><p>{copy(lang,'页面可能已调整，或尚未发布。让我们从首页重新出发。','This page may have moved or is not published yet. Let’s head back home.')}</p><Link className="site-button site-button-primary" to="/">{copy(lang,'返回首页','Back to home')}<ArrowUpRight size={18}/></Link></section>}

export default function PublicSite(){
  const [lang,setLanguage]=useState(()=>{try{return localStorage.getItem('cct-language')==='en'?'en':'zh'}catch{return 'zh'}});
  const [data,setData]=useState(null),[loading,setLoading]=useState(true),[error,setError]=useState(''),[reload,setReload]=useState(0);
  const location=useLocation();
  const previousPath=useRef(location.pathname);
  const setLang=next=>{setLanguage(next);try{localStorage.setItem('cct-language',next)}catch{}};
  useEffect(()=>{if(staticSite){setData(staticBootstrap);setLoading(false);setError('');return undefined;}const controller=new AbortController();setLoading(true);setError('');fetch('/api/public/bootstrap',{signal:controller.signal}).then(async r=>{if(!r.ok)throw new Error('load');return r.json()}).then(setData).catch(err=>{if(err.name!=='AbortError')setError('load')}).finally(()=>{if(!controller.signal.aborted)setLoading(false)});return()=>controller.abort()},[reload]);
  useEffect(()=>{window.scrollTo(0,0);document.documentElement.lang=lang==='zh'?'zh-CN':'en';const found=routeNames[location.pathname];const detail=location.pathname.startsWith('/content/')?data?.content?.find(item=>`/content/${item.slug}`===location.pathname):null;document.title=detail?`${value(detail,'title',lang)} · CCT`:found?`${found[lang==='zh'?0:1]} · CCT`:lang==='zh'?'CCT 算链 · AI 产业计算网络':'CCT Compute Chain · AI Industrial Network';},[location.pathname,lang,data]);
  useEffect(()=>{if(previousPath.current!==location.pathname){previousPath.current=location.pathname;requestAnimationFrame(()=>document.getElementById('site-main')?.focus({preventScroll:true}));}},[location.pathname]);
  return <SiteContext.Provider value={{lang,setLang,data,loading}}><div className="site"><a className="site-skip" href="#site-main" onClick={event=>{event.preventDefault();document.getElementById('site-main')?.focus();}}>{copy(lang,'跳到正文','Skip to content')}</a><Header/><main id="site-main" tabIndex={-1}>{error?<section className="site-container site-load-error"><AlertCircle size={35}/><h1>{copy(lang,'内容暂时无法加载。','Content is temporarily unavailable.')}</h1><p>{copy(lang,'请检查连接并重试。','Please check your connection and try again.')}</p><button className="site-button site-button-primary" onClick={()=>setReload(n=>n+1)}>{copy(lang,'重新加载','Try again')}</button></section>:<Routes><Route path="/" element={<HomePage/>}/><Route path="/business" element={<BusinessPage/>}/><Route path="/services" element={<CollectionPage type="service"/>}/><Route path="/solutions" element={<CollectionPage type="solution"/>}/><Route path="/opportunities" element={<OpportunitiesPage/>}/><Route path="/insights" element={<CollectionPage type="insight"/>}/><Route path="/ecosystem" element={<EcosystemPage/>}/><Route path="/about" element={<AboutPage/>}/><Route path="/contact" element={<ContactPage/>}/><Route path="/content/:slug" element={<DetailPage/>}/><Route path="/privacy" element={<LegalPage type="privacy"/>}/><Route path="/terms" element={<LegalPage type="terms"/>}/><Route path="*" element={<NotFound/>}/></Routes>}</main><Footer/></div></SiteContext.Provider>;
}
